def chain_chain(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []
        chain_dict[token].append(token)

    chain_dict = sorted(chain_dict.items(), key=lambda x: (-len(x[1]), x[0]))

    result = []
    current_token = chain_dict[0][0]
    for token in chain_dict:
        if token[0] == current_token:
            result.append(token[1])
            current_token = token[1][-1]

    return ','.join(result)

